var t=[{title:`Wat als HIIT telt`,text:`HIIT vraagt werk dat zwaar is voor je huidige fitheid, meestal gevolgd door een rustiger interval waarmee je weer een goede inspanning kunt leveren. Zwaar ademen wordt verwacht, maar de controle over je techniek verliezen niet. Door circuits razen geeft niet automatisch hetzelfde trainingseffect als gestructureerde aerobe intervallen met hoge intensiteit.`},{title:`Wat Tabata is`,text:`Het klassieke Tabata-formaat is acht rondes van 20 seconden zwaar werk en 10 seconden rust, in totaal vier minuten. Het oorspronkelijke onderzoek gebruikte zeer intensieve fietsinspanningen, dus een casual circuit van 20/10 kun je beter “Tabata-achtig” noemen, tenzij de inspanning vergelijkbaar is. Ook een kort protocol vraagt vooraf om een warming-up en achteraf om herstel.`},{title:`Wie eenvoudiger moet beginnen`,text:`Kom je terug na een pauze van activiteit of leer je nieuwe bewegingen, dan kunnen een paar weken comfortabel aeroob werk eerst beter voor je zijn. Heb je een medische aandoening die erdoor kan worden beïnvloed, vraag dan je arts voordat je begint. Burpees en sprongen zijn niet nodig om cardio intensief te maken, en een stationaire fiets kan veiliger en makkelijker te beheersen zijn.`},{title:`Beperk het zware werk`,text:`Begin met korte intervallen die je met goede vorm kunt afmaken en laat genoeg rustige dagen tussen zware trainingen. Frequentie, intensiteit en rondes tegelijk verhogen kan vermoeidheid geven zonder extra voordeel. HIIT is één optie naast gestage activiteit, krachttraining en dagelijks wandelen, en je kunt fit worden zonder.`}];var a=[{label:`ACE: hoogintensieve intervallen opzetten`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`ACE: het oorspronkelijke Tabata-intervalformaat`,url:`https://www.acefitness.org/continuing-education/prosource/hiit-special-issue/3743/is-tabata-all-it-s-cracked-up-to-be/`},{label:`Beweegaanbevelingen van de CDC voor volwassenen`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};